import threading
import queue
import time

q = queue.Queue(maxsize=10)

def producer():
    for i in range(5):
        q.put(f'item-{i}')
        time.sleep(0.1)
    q.put(None)  # Sentinel

def consumer():
    while True:
        item = q.get()
        if item is None:
            q.task_done()
            break
        print(f'Consumed {item}')
        q.task_done()

