from functools import lru_cache
from openai import OpenAI
import hashlib
import json
import os
import time

client = OpenAI(api_key=os.environ.get('OPENAI_API_KEY'))

# Exact match cache
class PromptCache:
    def __init__(self, maxsize=100):
        self._cache = {}
        self._maxsize = maxsize

    def _make_key(self, messages):
        return hashlib.sha256(json.dumps(messages, sort_keys=True).encode()).hexdigest()

    def get(self, messages):
        key = self._make_key(messages)
        return self._cache.get(key)

    def set(self, messages, response):
        key = self._make_key(messages)
        if len(self._cache) >= self._maxsize:
            self._cache.pop(next(iter(self._cache)))
        self._cache[key] = response

cache = PromptCache()

def cached_completion(messages):
    if cached := cache.get(messages):
        print('Cache hit!')
        return cached

    response = client.chat.completions.create(
        model='gpt-4o-mini',
        messages=messages
    )
    result = response.choices[0].message.content
    cache.set(messages, result)
    return result

# Prompt compression (reduce token count)
def compress_prompt(text, target_ratio=0.5):
    response = client.chat.completions.create(
        model='gpt-4o-mini',
        messages=[
            {'role': 'system', 'content': f'Compress this text to {target_ratio:.0%} of original while preserving key information.'},
            {'role': 'user', 'content': text}
        ]
    )
    return response.choices[0].message.content

